import inspect as _ins; print(_ins.signature(is_ring))
def applyH(g, rk, pk, rrev=False, prev=True):
    H=len(g); W=len(g[0]); out=[[0]*W for _ in range(H)]; sh=comps(g)
    cls=lambda s: is_ring(s)
    def put(cells):
        for y,x in cells: out[y][x]=g[y][x]
    rings=sorted([s for s in sh if cls(s)], key=rk, reverse=rrev)
    y=0
    for s in rings:
        cells={(yy-y,xx) for yy,xx in s['cells']}
        clash=any(out[yy][xx] for yy,xx in cells if 0<=yy<H)
        while clash:
            y+=1
            cells={(yy-y,xx) for yy,xx in s['cells']}
            clash=any(out[yy][xx] for yy,xx in cells if 0<=yy<H)
        put(cells)
    pl=sorted([s for s in sh if not cls(s)], key=pk, reverse=prev)
    y=H-1
    for s in pl:
        h=s['bot']-s['top']
        cells={(yy-(H-1-y-h),xx) for yy,xx in s['cells']}
        clash=any(out[yy][xx] for yy,xx in cells if 0<=yy<H)
        while clash:
            y-=1
            cells={(yy-(H-1-y-h),xx) for yy,xx in s['cells']}
            clash=any(out[yy][xx] for yy,xx in cells if 0<=yy<H)
        put(cells)
    return out
